from __future__ import print_function
import struct

# Full Karli SCFU packet body after N3 header - use complete hex from packets.hex
hexstr = (
"000F000A0001013A00000DB17996C028271B3A6B0000C350799AD394003A0A0B4ACB00001F494210964C3EDEB8514237AD58000000003F25312F000000003F4391E1"
""
)
# Fix: I may have corrupted hex - use exact from packets.hex.log line
hexstr = ""

raw = bytes.fromhex(hexstr)
# find texture marker 000017A6 after waypoints
marker = bytes.fromhex("000017A6")
idx = raw.find(marker)
print("first marker", idx)
p = idx + 4
for i in range(5):
    place, tid, unk = struct.unpack_from(">III", raw, p)
    print("tex", i, "place", place, "id", tid, "unk", unk)
    p += 12
print("at mesh marker?", raw[p:p+4].hex(), "expect 000017a6")
assert raw[p:p+4] == marker
p += 4
for i in range(5):
    pos = raw[p]; p += 1
    mid = struct.unpack_from(">I", raw, p)[0]; p += 4
    ovr = struct.unpack_from(">i", raw, p)[0]; p += 4
    layer = raw[p]; p += 1
    print("mesh", i, "pos", pos, "id", mid, "ovr", ovr, "layer", layer)
print("remain", raw[p:].hex())
